int total(int arr[], int size) {
    int i;
    int sum = 0;
    for (i = 0; i < size; i++) {
        sum = sum + arr[i];
    }
    return sum;
}

int scores[5] = {90, 85, 78, 92, 88};
printf("%d", total(scores, 5));

int countAbove(int arr[], int size, int limit) {
    int i;
    int count = 0;
    for (i = 0; i < size; i++) {
        if (arr[i] > limit) {
            count++;
        }
    }
    return count;
}

int marks[5] = {70, 95, 60, 88, 91};
printf("%d", countAbove(marks, 5, 85));
